content.text:
:root {
  --color-background: oklch(14.5% 0 0);
  --color-foreground: oklch(87% 0.004 250);
  --color-card: oklch(20.5% 0 0);
  --color-card-foreground: oklch(92% 0.004 250);
  --color-card-hover: oklch(30.5% .0006 250);
  --color-popover: oklch(23.5% 0 0);
  --color-popover-foreground: oklch(87% 0.004 250);
  --color-muted: oklch(17.5% 0 0);
  --color-muted-foreground: oklch(65% 0.010 250);
  --color-secondary: oklch(30% 0 0);
  --color-secondary-foreground: oklch(90% 0.004 250);
  --color-border: oklch(30% 0.004 250);
  --color-border-soft: oklch(26% 0 0);
  --color-input: oklch(36% 0.004 250);
  --color-surface-skeleton: oklch(25% 0 0);
  --color-primary: oklch(54.6% 0.245 262.9);
  --color-primary-foreground: oklch(100% 0 0);
  --color-primary-hover: oklch(48.8% 0.243 264.4);
  --color-primary-text: oklch(70.7% 0.165 254.6);
  --color-primary-subtle: oklch(23.2% 0.020 262.9);
  --color-ring: var(--color-primary);
  --color-destructive: oklch(58% 0.210 25);
  --color-destructive-foreground: oklch(100% 0 0);
  --color-destructive-hover: oklch(50% 0.210 25);
  --color-destructive-text: oklch(70% 0.170 25);
  --color-warning: oklch(75% 0.140 85);
  --color-success: oklch(70% 0.150 145);
  --color-info: oklch(70% 0.150 250);
  --color-sidebar: oklch(12.5% 0 0);
  --color-sidebar-foreground: oklch(80% 0.004 250);
  --color-sidebar-primary: oklch(30% 0 0);
  --color-sidebar-primary-foreground: oklch(92% 0.004 250);
  --color-sidebar-accent: oklch(9.5% 0 0);
  --color-sidebar-accent-foreground: oklch(80% 0.004 250);
  --color-sidebar-border: oklch(28% 0.003 250);
  --color-sidebar-ring: var(--color-primary);
  --font-sans: Inter;
  --text-base: 16px;
  --text-lg: 18px;
  --text-xl: 20px;
  --text-2xl: 24px;
  --text-3xl: 30px;
  --text-4xl: 36px;
  --text-5xl: 48px;
  --font-weight-normal: 400;
  --font-weight-medium: 500;
  --font-weight-semibold: 600;
  --font-weight-bold: 700;
  --tracking-tight: -0.025em;
  --tracking-overline: 0.03em;
  --leading-caption: 20px;
  --leading-body: 24px;
  --leading-h4: 28px;
  --leading-h2: 32px;
  --leading-h1: 36px;
  --leading-display: 40px;
  --opacity-disabled: 50%;
  --breakpoint-sm: 640px;
  --breakpoint-md: 768px;
  --breakpoint-lg: 1024px;
  --breakpoint-xl: 1280px;
  --container-5xl: 1024px;
  --spacing-1: 4px;
  --spacing-2: 8px;
  --spacing-3: 12px;
  --spacing-4: 16px;
  --spacing-5: 20px;
  --spacing-6: 24px;
  --spacing-8: 32px;
  --spacing-9: 36px;
  --spacing-11: 44px;
  --spacing-12: 48px;
  --spacing-header: 64px;
  --spacing-gutter: 16px;
  --spacing-gutter-md: 20px;
  --spacing-gutter-lg: 32px;
  --radius-sm: 4px;
  --radius-md: 8px;
  --radius-lg: 12px;
  --radius-xl: 14px;
  --radius-2xl: 16px;
  --radius-sheet: 20px;
  --radius-3xl: 24px;
  --radius-full: 9999px;
}
